1	/* ===== Đồng hồ theo múi giờ chỉ định (D-042) =====
2	   Chỉ dùng Intl, không đụng DOM: chạy được dưới Node. Giờ tính theo `tz` (Đà Nẵng), không theo múi giờ máy khách. */
3	
4	export type EnvPhase = 'dawn' | 'day' | 'dusk' | 'night';
5	
6	const fmtCache = new Map<string, Intl.DateTimeFormat>();   // một bộ định dạng cho mỗi múi giờ (tạo Intl khá tốn)
7	
8	function envFmt(tz: string): Intl.DateTimeFormat {
9	  let f = fmtCache.get(tz);
10	  if (!f) {
11	    f = new Intl.DateTimeFormat('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' });
12	    fmtCache.set(tz, f);
13	  }
14	  return f;
15	}
16	
17	/** Giờ / phút / giây tại múi giờ `tz`; min = h*60+m. Chữ số Latin, 0–23 (nửa đêm là 0, không phải 24). */
18	export function envClockParts(d: Date, tz: string): { h: number; m: number; s: number; min: number } {
19	  let h = 0, m = 0, s = 0;
20	  for (const p of envFmt(tz).formatToParts(d)) {
21	    if (p.type === 'hour') h = parseInt(p.value, 10) % 24;
22	    else if (p.type === 'minute') m = parseInt(p.value, 10);
23	    else if (p.type === 'second') s = parseInt(p.value, 10);
24	  }
25	  return { h, m, s, min: h * 60 + m };
26	}
27	
28	/** 348 → "05:48" */
29	export function envHHMM(min: number): string {
30	  const p = (n: number) => (n < 10 ? '0' : '') + n;
31	  return p(Math.floor(min / 60) % 24) + ':' + p(Math.floor(min % 60));
32	}
33	
34	/** Pha trong ngày theo phút; bình minh / hoàng hôn xét trước, rồi ngày, còn lại là đêm. */
35	export function envPhase(min: number, sunrise: number, sunset: number, dawn: readonly [number, number], dusk: readonly [number, number]): EnvPhase {
36	  if (min >= sunrise + dawn[0] && min < sunrise + dawn[1]) return 'dawn';
37	  if (min >= sunset + dusk[0] && min < sunset + dusk[1]) return 'dusk';
38	  if (min >= sunrise && min < sunset) return 'day';
39	  return 'night';
40	}
