1	/* ===== Kho trạng thái số liệu thực tế (D-042) =====
2	   Lấy Open-Meteo theo nhịp, thử lại lùi mũ, bộ nhớ đệm localStorage. Mọi thứ ngoài (fetch, giờ, hẹn giờ, storage) được tiêm vào để chạy dưới Node. */
3	import type { CONFIG } from '../config';
4	import { envUrl, envParse, envIsWeather, type EnvWeather } from './weatherApi';
5	
6	export type EnvStatus = 'loading' | 'ok' | 'stale' | 'offline';
7	export type EnvDeps = {
8	  cfg: typeof CONFIG.env; live: boolean;                         // live=false: không bao giờ gọi fetch
9	  fetch: (url: string, init?: { signal?: AbortSignal }) => Promise<{ ok: boolean; json(): Promise<unknown> }>;
10	  now: () => number; storage: { getItem(k: string): string | null; setItem(k: string, v: string): void } | null;
11	  setTimer: (fn: () => void, ms: number) => unknown; clearTimer: (id: unknown) => void;
12	};
13	export type EnvStore = {
14	  readonly data: EnvWeather | null; status(): EnvStatus;
15	  start(): void; stop(): void; refresh(): Promise<void>; setVisible(v: boolean): void;
16	  onChange(fn: () => void): void;
17	  inject(data: EnvWeather | null, failed?: boolean): void;       // cho test trình duyệt: đặt thẳng số liệu / trạng thái lỗi rồi báo onChange
18	};
19	
20	export function createEnvStore(d: EnvDeps): EnvStore {
21	  const cfg = d.cfg;
22	  let data: EnvWeather | null = null;
23	  let failed = false;                      // có ít nhất một lần lấy lỗi kể từ lần thành công gần nhất
24	  let nFail = 0;                           // số lần lỗi liên tiếp (mũ của thời gian chờ)
25	  let started = false, visible = true;
26	  let inflight: Promise<void> | null = null;
27	  let timer: unknown = null, nextAt = 0;   // hẹn lấy kế tiếp; nextAt = 0: chưa từng hẹn
28	  const subs: Array<() => void> = [];
29	
30	  const emit = () => { for (const f of subs) { try { f(); } catch (e) { console.error(e); } } };   // một listener ném không chặn listener khác, không thành lời hứa bị từ chối chưa xử lý
31	  const clear = () => { if (timer !== null) { d.clearTimer(timer); timer = null; } };
32	  const arm = (ms: number) => {
33	    clear();
34	    nextAt = d.now() + ms;
35	    if (visible && started) timer = d.setTimer(() => { timer = null; void refresh(); }, ms);
36	  };
37	
38	  /* Đọc bộ nhớ đệm: hỏng / sai kiểu thì bỏ, không ném */
39	  const loadCache = () => {
40	    if (!d.storage) return;
41	    try {
42	      const raw = d.storage.getItem(cfg.storeKey);
43	      if (!raw) return;
44	      const o = JSON.parse(raw);
45	      if (envIsWeather(o)) data = o;
46	    } catch { /* bỏ qua */ }
47	  };
48	  const saveCache = () => {
49	    if (!d.storage || !data) return;
50	    try { d.storage.setItem(cfg.storeKey, JSON.stringify(data)); } catch { /* đầy / bị chặn: bỏ qua */ }
51	  };
52	
53	  /* Một lần lấy: ném / ok=false / JSON hỏng / quá timeoutMs đều là lỗi */
54	  const fetchOnce = async (): Promise<EnvWeather | null> => {
55	    const ac = typeof AbortController !== 'undefined' ? new AbortController() : null;
56	    let tid: unknown = null;
57	    const timeout = new Promise<never>((_, rej) => {
58	      tid = d.setTimer(() => { try { ac && ac.abort(); } catch { /* bỏ qua */ } rej(new Error('timeout')); }, cfg.timeoutMs);
59	    });
60	    try {
61	      const work = (async () => {
62	        const res = await d.fetch(envUrl(cfg), ac ? { signal: ac.signal } : undefined);
63	        if (!res || !res.ok) return null;
64	        return envParse(await res.json());
65	      })();
66	      work.catch(() => { /* tránh báo lỗi chưa xử lý khi timeout thắng cuộc đua */ });
67	      return await Promise.race([work, timeout]);
68	    } catch {
69	      return null;
70	    } finally {
71	      d.clearTimer(tid);
72	    }
73	  };
74	
75	  const run = async (): Promise<void> => {
76	    const w = await fetchOnce();
77	    if (w) {
78	      data = w; failed = false; nFail = 0;
79	      saveCache();
80	      arm(cfg.refreshMs);
81	    } else {
82	      failed = true;
83	      arm(Math.min(cfg.retryMs * Math.pow(2, nFail), cfg.retryMaxMs));
84	      nFail++;
85	    }
86	    emit();
87	  };
88	
89	  function refresh(): Promise<void> {
90	    if (!d.live) return Promise.resolve();
91	    if (inflight) return inflight;
92	    clear();
93	    inflight = run().finally(() => { inflight = null; });
94	    return inflight;
95	  }
96	
97	  return {
98	    get data() { return data; },
99	    status(): EnvStatus {
100	      if (!data) return failed ? 'offline' : 'loading';
101	      return d.now() - data.obs <= cfg.staleMs ? 'ok' : 'stale';
102	    },
103	    start() {
104	      if (started) return;
105	      started = true;
106	      loadCache();
107	      if (data) emit();
108	      if (d.live && visible) void refresh();
109	    },
110	    stop() { started = false; clear(); },
111	    refresh,
112	    setVisible(v: boolean) {
113	      if (v === visible) return;
114	      visible = v;
115	      if (!started || !d.live) return;
116	      if (!v) { clear(); return; }
117	      if (inflight) return;                                    // đang lấy: xong sẽ tự hẹn
118	      if (nextAt === 0 || d.now() >= nextAt) void refresh();   // đã quá hạn (hoặc chưa từng lấy): lấy ngay
119	      else arm(nextAt - d.now());                              // chưa tới hạn: hẹn phần còn lại
120	    },
121	    onChange(fn: () => void) { subs.push(fn); },
122	    inject(v: EnvWeather | null, f?: boolean) { data = v; failed = !!f; emit(); }
123	  };
124	}
