63	  if (!seg) return;
64	  const update = () => {
65	    const max = seg.scrollWidth - seg.clientWidth;
66	    const pos = Math.abs(seg.scrollLeft);   // quãng đã cuộn từ đầu dòng, đúng cả LTR lẫn RTL
67	    seg.classList.toggle('more-start', ui.compact && pos > 8);
68	    seg.classList.toggle('more-end', ui.compact && max - pos > 8);
69	  };
70	  seg.addEventListener('scroll', update, { passive: true });
71	  window.addEventListener('resize', update);
72	  segFadeUpdate = update;
73	  if (typeof ResizeObserver !== 'undefined') new ResizeObserver(update).observe(seg);
74	  onChange(update);   // đổi ngôn ngữ đổi bề rộng chip nhưng không đổi hộp .seg nên ResizeObserver không báo
75	}
76	let segFadeUpdate = () => {};
