81	  new MutationObserver(() => {
82	    const on = document.body.classList.contains('touring') || document.body.classList.contains('wxrun');
83	    if (on && !was && ui.sheet !== 'none') closeSheets();
84	    was = on;
85	  }).observe(document.body, { attributes: true, attributeFilter: ['class'] });
86	}
